 private static void protection(){var p=new BlockPos(132,180,64);for(Block block:List.of(Blocks.REDSTONE_WIRE,Blocks.PISTON,Blocks.WATER,Blocks.CHEST,Blocks.FURNACE,Blocks.CRAFTING_TABLE,net.minecraft.core.registries.BuiltInRegistries.BLOCK.get(net.minecraft.resources.ResourceLocation.parse("minecraft:red_bed")),Blocks.WHEAT,Blocks.OAK_DOOR,Blocks.OAK_SIGN,Blocks.SPAWNER,Blocks.BEACON,Blocks.TORCH,Blocks.LADDER,Blocks.RAIL)){
  QuietPlacement.setBlock(world,p,block.defaultBlockState(),QUIET);check(ReplacementRules.protectedBlock(world,p,world.getBlockState(p),true),"protected block missed: "+block);
 }QuietPlacement.setBlock(world,p,Blocks.OAK_SLAB.defaultBlockState().setValue(BlockStateProperties.WATERLOGGED,true),QUIET);check(ReplacementRules.protectedBlock(world,p,world.getBlockState(p),true),"waterlogged block missed");QuietPlacement.setBlock(world,p,Blocks.STONE.defaultBlockState(),QUIET);check(!ReplacementRules.protectedBlock(world,p,world.getBlockState(p),false),"ordinary stone protected");QuietPlacement.setBlock(world,p,Blocks.BEDROCK.defaultBlockState(),QUIET);check(ReplacementRules.protectedBlock(world,p,world.getBlockState(p),false),"survival bedrock unprotected");check(!ReplacementRules.protectedBlock(world,p,world.getBlockState(p),true),"creative bedrock unexpectedly protected");}
